"""Binary64 arithmetic and exact integral conversions in BigInt mode."""
import ast
import shutil
import unittest
from py2fastrust.frontend import build_program
from tests import test_native_frame_splits as text_helpers


class BigIntRealCapabilityTests(unittest.TestCase):
    def test_ordinary_integral_ratio_and_integer_loops_keep_static_selection(self):
        from py2fastrust.native_frame_selection import select_frames
        for source in ["print(7/2)\n", "total=0\nfor value in range(8):total+=value\nprint(total)\n"]:
            self.assertFalse(select_frames(build_program(source,'main.py').main,integer='bigint').required)

    def test_original_ast_and_scope_nodes_are_retained(self):
        from py2fastrust.native_classes import try_generate_classes
        source="class Box:\n def run(self,left,right):return left+right,left/right\nprint(Box().run(7,2.0))\n"
        unit=build_program(source,'main.py').main
        before=ast.dump(unit.tree,include_attributes=True);nodes=tuple(ast.walk(unit.tree))
        self.assertIsNotNone(try_generate_classes(source,'main.py','bigint',unit=unit))
        self.assertEqual(ast.dump(unit.tree,include_attributes=True),before)
        self.assertEqual(tuple(ast.walk(unit.tree)),nodes)


@unittest.skipUnless(shutil.which('rustc'),'rustc is required')
class BigIntRealExecutionTests(unittest.TestCase):
    exercise=text_helpers.SplitExecutionTests.exercise

    def test_ordinary_real_ops(self):
        self.exercise('print(1.5+2.25,1.5-2.25,1.5*2.25,1.5/2.25,1.5//2.25,1.5%2.25)\n')

    def test_framed_real_ops(self):
        self.exercise('class Box:\n def run(self):\n  for left,right in [(1.5,2.25),(-1.5,2.25),(1.5,-2.25),(-1.5,-2.25),(0.0,-2.0),(-0.0,2.0)]:print(left+right,left-right,left*right,left/right,left//right,left%right)\nBox().run()\n')

    def test_ordinary_mixed_ops(self):
        self.exercise('print(7+0.5,7-0.5,7*0.5,7/0.5,7//0.5,7%0.5)\nprint(0.5+7,0.5-7,0.5*7,0.5/7,0.5//7,0.5%7)\n')

    def test_framed_mixed_ops(self):
        self.exercise('class Box:\n def run(self):\n  for left,right in [(7,0.5),(-7,0.5),(7,-0.5),(True,0.5),(False,-0.5)]:print(left+right,left-right,left*right,left/right,left//right,left%right)\nBox().run()\n')

    def test_finite_numeric_union(self):
        self.exercise('class Box:\n def calc(self,left,right):return left+right,left-right,left*right,left/right,left//right,left%right\nb=Box()\nprint(b.calc(7,2.0))\nprint(b.calc(7.0,2))\nprint(b.calc(7.0,2.0))\n')

    def test_nan_arithmetic(self):
        self.exercise('class Box:\n def run(self):\n  print(1e999-1e999,1e999+(-1e999),0.0*1e999,1e999/1e999)\nBox().run()\n')

    def test_signed_zero(self):
        self.exercise('class Box:\n def run(self):\n  print(0.0/-2.0,-0.0/2.0,0.0*-2.0,-0.0+(-0.0),-0.0%2.0,0.0%-2.0)\nBox().run()\n')

    def test_mixed_float_rounding(self):
        self.exercise('class Box:\n def run(self):\n  print(9007199254740993+0.0,9007199254740995-0.0,9007199254740993*1.0,9007199254740993/3.0)\nBox().run()\n')

    def test_subnormal(self):
        self.exercise('class Box:\n def run(self):\n  print(5e-324*2.0,5e-324/2.0,5e-324//2.0,5e-324%2.0,-5e-324%2.0)\nBox().run()\n')

    def test_mixed_overflow(self):
        self.exercise('class Box:\n def run(self):\n  print((1<<2000)+1.0)\nBox().run()\n',expected_by_integer={'i64': ('1.0\n', '', 0), 'i128': ('1.0\n', '', 0)})

    def test_eval_order(self):
        self.exercise("def left():\n print('left')\n return 7\ndef right():\n print('right')\n return 2.0\nprint(left()/right())\n")

    def test_zero_true_div(self):
        self.exercise('class Box:\n def run(self):\n  print(1.0/0.0)\nBox().run()\n')

    def test_zero_floor_div(self):
        self.exercise('class Box:\n def run(self):\n  print(1.0//0.0)\nBox().run()\n')

    def test_zero_modulo(self):
        self.exercise('class Box:\n def run(self):\n  print(1.0%0.0)\nBox().run()\n')

    def test_exact_integer_ratio_witness(self):
        self.exercise('print(9007199254740993/3)\n')

    def test_exact_integer_ratio_framed_witness(self):
        self.exercise('class Box:\n def run(self):\n  print(9007199254740993/3)\nBox().run()\n')

